function run(input, params, h) {
  const first = String(params.first).toUpperCase() === "O" ? "O" : "X";
  const game = input.memory || { board: ["", "", "", "", "", "", "", "", ""], next: first, over: false };
  const board = game.board.slice();
  const rows = [[1, 2, 3], [4, 5, 6], [7, 8, 9], [1, 4, 7], [2, 5, 8], [3, 6, 9], [1, 5, 9], [3, 5, 7]];
  const freeSquares = () => board.map((mark, i) => (mark ? 0 : i + 1)).filter(n => n > 0).join(", ");
  const show = () => ["top", "middle", "bottom"].map((row, r) => row + ": " + [0, 1, 2].map(c => board[3 * r + c] || String(3 * r + c + 1)).join(" ")).join("\n");
  const center = n => [((n - 1) % 3) * 120 - 120, 120 - Math.floor((n - 1) / 3) * 120];
  const drawing = win => {
    let logo = "SETPENSIZE 4 SETPENCOLOR \"black\n";
    for (const k of [-60, 60]) {
      logo += "PENUP SETXY " + k + " 180 PENDOWN SETXY " + k + " -180\n";
      logo += "PENUP SETXY -180 " + k + " PENDOWN SETXY 180 " + k + "\n";
    }
    for (let n = 1; n <= 9; n++) {
      h.tick();
      const x = center(n)[0], y = center(n)[1], mark = board[n - 1];
      if (mark === "X") logo += "SETPENCOLOR \"blue SETPENSIZE 8 PENUP SETXY " + (x - 35) + " " + (y + 35) + " PENDOWN SETXY " + (x + 35) + " " + (y - 35) + " PENUP SETXY " + (x - 35) + " " + (y - 35) + " PENDOWN SETXY " + (x + 35) + " " + (y + 35) + "\n";
      else if (mark === "O") logo += "SETPENCOLOR \"red SETPENSIZE 8 PENUP SETXY " + x + " " + y + " PENDOWN CIRCLE 38\n";
      else logo += "SETPENCOLOR \"gray PENUP SETXY " + (x - 6) + " " + (y - 8) + " LABEL [" + n + "]\n";
    }
    if (win) logo += "SETPENCOLOR \"green SETPENSIZE 10 PENUP SETXY " + center(win[0]).join(" ") + " PENDOWN SETXY " + center(win[2]).join(" ") + "\n";
    return logo;
  };
  if (!input.memory) {
    return { next: first, over: false, board: board, program: drawing(null), say: "New game! " + first + " goes first.\n\n" + show() + "\n\n" + first + " to play: pick a free square: " + freeSquares() + ".", memory: game };
  }
  if (game.over) {
    return { pass: false, next: "", over: true, say: "The game is over.", memory: game };
  }
  let move = null;
  for (const word of h.words(input.text)) {
    h.tick();
    const n = Number(word);
    if (move === null && Number.isInteger(n) && n >= 1 && n <= 9) move = n;
  }
  if (move === null) {
    return { pass: false, next: game.next, over: false, say: "Please pick a free square: " + freeSquares() + ".", memory: game };
  }
  if (board[move - 1]) {
    return { pass: false, next: game.next, over: false, move: move, taken: true, say: "Square " + move + " is already taken by " + board[move - 1] + ". Please pick a free square: " + freeSquares() + ".", memory: game };
  }
  const player = game.next;
  board[move - 1] = player;
  const win = rows.find(r => board[r[0] - 1] === player && board[r[1] - 1] === player && board[r[2] - 1] === player);
  if (win) {
    return { pass: true, move: move, next: "", over: true, winner: player, board: board, program: drawing(win), say: player + " takes square " + move + " and wins with " + win.join(", ") + "!\n\n" + show(), memory: { board: board, next: "", over: true } };
  }
  if (board.every(mark => mark)) {
    return { pass: true, move: move, next: "", over: true, winner: "nobody", board: board, program: drawing(null), say: player + " takes square " + move + ". It's a draw!\n\n" + show(), memory: { board: board, next: "", over: true } };
  }
  const next = player === "X" ? "O" : "X";
  return { pass: true, move: move, next: next, over: false, board: board, program: drawing(null), say: player + " takes square " + move + ".\n\n" + show() + "\n\n" + next + " to play: pick a free square: " + freeSquares() + ".", memory: { board: board, next: next, over: false } };
}
